import { $, esc, icon, money, dateText, dateTime, localDateValue, browserZone, api, toast, empty, confirmAction } from './utils.js';
import { ratingTag, reviewsRoot, hydrateReviews, initReviews } from './reviews.js';
import { accountPage, deleteAccountDialog } from './account.js';
import { statsStrip, techMarquee, howItWorks, whyUs, testimonials, faq, siteFooter } from './home-sections.js';
let user=null,demo=true,demoEmail='admin@cathlab.dev',courses=[],reels=[],lectures=[],notices=[],routeToken=0;
let editing=null,checkoutCourse=null,search='',category='All',uploadsInFlight=0;
let scheduleFilter='upcoming',paymentFilter='all',seenAt=localStorage.getItem('medcircle-seen')||'';
const main=$('#main');
initReviews({user:()=>user});
function brand(){return '<a class="brand" href="#/"><span class="brandmark">+</span>Cath Lab Insights</a>';} //<small></small>
function header(){
 const route=location.hash||'#/';const unread=notices.filter(n=>n.created>seenAt).length;
 $('#header').innerHTML=`<nav class="nav" aria-label="Main navigation">${brand()}<div class="navlinks" id="navlinks"><a class="${route==='#/'?'active':''}" href="#/">Home</a><a class="${route.includes('course')?'active':''}" href="#/courses">Courses</a><a class="${route.includes('schedule')?'active':''}" href="#/schedule">Live lectures</a><a class="${route.includes('reels')?'active':''}" href="#/reels">Reels</a><a class="${route.includes('notices')?'active':''}" href="#/notices">Notices ${unread?`<span class="notice-dot" aria-label="${unread} unread">${unread}</span>`:''}</a></div><div class="navactions">${user?`<a class="btn small" href="${user.role==='admin'?'#/admin':'#/account'}">${user.role==='admin'?'Dashboard':'My account'} ${icon('arrow')}</a><a class="textbtn" href="#/account" aria-label="Your account">${icon('users')}</a>`:`<a class="textbtn" href="#/login">Log in</a><a class="btn" href="#/signup">Join the circle ${icon('arrow')}</a>`}<button class="menu" data-action="menu" aria-label="Toggle navigation" aria-expanded="false">${icon('menu')}</button></div></nav>`;
 $('#footer').innerHTML=siteFooter(brand(),user);
}
function cover(c,rate=false){return `<div class="cover ${esc(c.color)}">${rate?ratingTag('course',c.id,c.rating):''}${c.thumbnail?`<img src="${esc(c.thumbnail)}" alt="${esc(c.title)}" loading="lazy">`:`<span class="medical-orbit"></span><span class="codeicon">${esc(c.icon)}</span><span class="cover-label">Cath Lab Insights / ${esc(c.category)}</span>`}<span class="pill">${esc(c.level)}</span></div>`;}
function badge(status){return `<span class="status ${['pending','draft','scheduled'].includes(status)?'draft':['rejected','revoked','cancelled','suspended'].includes(status)?'suspended':''}">${esc(status)}</span>`;}
function card(c){return `<a class="course-card" href="#/course/${c.id}">${cover(c,true)}<div class="card-body"><div class="card-kicker"><span>${esc(c.category)}</span><span>LIVE ON ZOOM</span></div><h3>${esc(c.title)}</h3><p>${esc(c.description)}</p><div class="course-price">${money(c.price,c.currency)} <small>one-time course fee</small></div><div class="card-foot"><span>${icon('calendar')} ${c.lectureCount} scheduled session${c.lectureCount===1?'':'s'}</span><b>${c.access?'View your course':c.order?.status==='pending'?'Payment in review':'View course'} ↗</b></div></div></a>`;}
function reelCard(r){return `<a class="reel-card" href="#/reels/${r.id}"><span class="pill">${esc(r.category)}</span><h3>${esc(r.title)}</h3><div class="reel-foot"><span>${r.video?'WATCH THE REEL':'SAMPLE REEL PREVIEW'}</span><span class="play">${icon('play')}</span></div></a>`;}
function lectureCard(l,compact=false){
 const d=new Date(l.starts_at);const live=l.status==='scheduled'&&Date.now()>=d.getTime();
 return `<article class="lecture-card ${compact?'compact':''}"><div class="date-tile"><span>${d.toLocaleDateString(undefined,{month:'short'})}</span><b>${d.getDate()}</b></div><div class="lecture-content"><div class="lecture-meta">${badge(live?'live now':l.status)}<span>${esc(l.course_title||'Live course')}</span></div><h3>${esc(l.title)}</h3><p class="lecture-time">${icon('calendar')} ${esc(dateTime(l.starts_at))} · ${l.duration} min</p>${!compact?`<p>${esc(l.description)}</p><div class="hint">${esc(l.speaker||'Instructor to be announced')}</div>`:''}</div><div class="lecture-action">${l.canJoin?`<button class="btn small" data-action="join-zoom" data-id="${l.id}">${icon('play')} Zoom link</button>`:l.status==='cancelled'||l.status==='completed'?badge(l.status):l.access?'<span class="hint">Zoom link coming soon</span>':`<a class="btn small outline" href="#/course/${l.course_id}">View course ${icon('arrow')}</a>`}</div></article>`;
}
function noticeCard(n){return `<article class="notice-card"><div class="notice-symbol">${icon(n.pinned?'bell':'book')}</div><div><div class="notice-meta">${n.pinned?'<span class="pill">PINNED</span>':''}<span>${n.course_id?esc(n.course_title):'Academy announcement'}</span><span>${dateText(n.created)}</span></div><h3>${esc(n.title)}</h3><p>${esc(n.body)}</p></div></article>`;}
async function home(){
 let latest;
 [courses,reels,lectures,notices,latest]=await Promise.all([api('/api/courses'),api('/api/reels'),api('/api/lectures'),api('/api/notices'),api('/api/reviews/latest')]);
 const next=lectures.find(l=>l.status==='scheduled');
 return `<div class="container"><section class="hero"><div><div class="eyebrow"><span class="dot"></span>A connected way to learn medicine</div><h1>Learn together.<br>Understand deeper.<br><span>Go further.</span></h1><p>Your medical learning circle, all in one place. Discover courses, catch the next live Zoom lecture, and stay close to every update.</p><div class="actions"><a class="btn" href="#/courses">Explore our courses ${icon('arrow')}</a><a class="btn outline" href="#/schedule">${icon('calendar')} Upcoming lectures</a></div><div class="micro"><span><b>✓</b> Live Zoom sessions</span><span><b>✓</b> Course updates</span><span><b>✓</b> Short learning reels</span></div></div><div class="medical-hero"><div class="medical-grid"></div><div class="hero-schedule"><div class="hero-schedule-head"><span class="pill">YOUR NEXT CHAPTER</span><span class="soft-icon">${icon('calendar')}</span></div><div class="hero-monogram">m<span>+</span></div><div class="eyebrow">Inside the learning circle</div><h2>${next?esc(next.title):'Your next live session awaits.'}</h2><p>${next?esc(dateTime(next.starts_at)):'See upcoming lectures and join a course.'}</p><div class="hero-schedule-foot"><span class="zoom-icon">${icon('play')}</span><div><b>Live on Zoom</b><small>Meet. Learn. Ask questions.</small></div><a class="round-link" href="#/schedule" aria-label="View lecture schedule">↗</a></div></div><div class="float-tag top"><span class="badge-icon">+</span><div><b>A shared learning journey.</b><small>One session at a time.</small></div></div><div class="float-tag bottom"><span class="badge-icon">${icon('bell')}</span><div><b>Stay in the loop</b><small>Lectures, notices and new ideas.</small></div></div></div></section>${techMarquee()}${statsStrip({courses,lectures,reels})}<section class="section"><div class="section-head"><div><div class="overline">Choose your next step</div><h2>A course. A community. A clearer path.</h2><p>One course fee. A place in the live learning circle.</p></div><a class="textbtn" href="#/courses">All courses ${icon('arrow')}</a></div><div class="grid">${courses.slice(0,3).map(card).join('')||empty('Your academy starts here','The instructor will publish courses here soon.')}</div></section><section class="section schedule-section"><div class="section-head"><div><div class="overline">Make room for learning</div><h2>Coming up in the circle.</h2><p>Live discussions and focused lectures. All times shown in your local time zone.</p></div><a class="textbtn" href="#/schedule">Full schedule ${icon('arrow')}</a></div><div class="lecture-stack">${lectures.filter(l=>l.status==='scheduled').slice(0,3).map(l=>lectureCard(l,true)).join('')||empty('The next session is on its way','Watch this space for your instructor’s schedule.')}</div></section>${howItWorks()}</div><section class="reel-section"><div class="container section"><div class="section-head"><div><div class="overline">Small moments of discovery</div><h2>A little learning, wherever you are.</h2><p>Course previews, short reels and updates from your instructor.</p></div><a class="textbtn" href="#/reels">Explore reels ${icon('arrow')}</a></div><div class="reel-grid">${reels.slice(0,3).map(reelCard).join('')||empty('New reels coming soon','Short updates will appear here.')}</div></div></section><div class="container"><section class="section"><div class="section-head"><div><div class="overline">From the noticeboard</div><h2>Good to know. Easy to find.</h2></div><a class="textbtn" href="#/notices">All notices ${icon('arrow')}</a></div>${notices.slice(0,2).map(noticeCard).join('')||empty('You’re all caught up','There are no announcements right now.')}</section>${whyUs()}${testimonials(latest)}${faq()}<section class="cta"><div><h2>Your learning circle is waiting.</h2><p>Create an account to follow your courses and stay connected.</p></div><a class="btn lime" href="${user?'#/courses':'#/signup'}">${user?'Find your course':'Join the circle'} ${icon('arrow')}</a></section></div>`;
}
async function catalogue(){courses=await api('/api/courses');return `<div class="container bottom-space"><div class="pagehead"><div class="overline">Learn with a plan</div><h1>Find your medical learning circle.</h1><p>Explore the syllabus, see upcoming lectures, and choose a course that fits your goals.</p></div><div class="toolbar"><div class="search">${icon('search')}<input id="course-search" placeholder="Search courses and subjects…" aria-label="Search courses" value="${esc(search)}"></div><select id="category-filter" aria-label="Category"><option>All</option>${[...new Set(courses.map(c=>c.category))].map(c=>`<option ${category===c?'selected':''}>${esc(c)}</option>`).join('')}</select></div><p id="result-count" class="count"></p><div id="course-grid" class="grid"></div></div>`;}
function filterCourses(){const grid=$('#course-grid');if(!grid)return;const list=courses.filter(c=>(category==='All'||c.category===category)&&`${c.title} ${c.category} ${c.description}`.toLowerCase().includes(search.toLowerCase()));$('#result-count').textContent=`${list.length} course${list.length===1?'':'s'}`;grid.innerHTML=list.map(card).join('')||empty('No courses found','Try a different search or category.');}
function auth(mode){const signup=mode==='signup';return `<div class="auth-wrap"><div class="auth-card">${brand()}<h1>${signup?'A place in the circle.':'Welcome back.'}</h1><p>${signup?'Create your free account. Course fees are paid separately.':'Your courses, lectures and updates are waiting.'}</p><form id="auth-form" data-mode="${mode}"><div class="form-error" role="alert"></div>${signup?'<label class="field">Your name<input name="name" required maxlength="80" autocomplete="name" placeholder="Full name"></label>':''}<label class="field">Email address<input name="email" required type="email" maxlength="254" autocomplete="email" placeholder="you@example.com"></label><label class="field">Password<input name="password" required type="password" minlength="${signup?10:1}" maxlength="128" autocomplete="${signup?'new-password':'current-password'}" placeholder="${signup?'At least 10 characters':'Enter your password'}"></label><button class="btn full">${signup?'Create account':'Sign in'} ${icon('arrow')}</button></form><div class="auth-bottom">${signup?'Already a member? <a href="#/login">Sign in</a>':'New to the circle? <a href="#/signup">Create an account</a>'}</div>${demo&&!signup?'<div class="demo-box"><button class="btn small light" data-action="fill-demo">Fill details</button><b>Try the admin dashboard</b><br>${esc(demoEmail)}<br>Admin@12345</div>':''}</div></div>`;}
async function courseDetail(id){
 const c=await api('/api/courses/'+id);
 return `<div class="container"><div class="detail-top"><a class="btn outline small" href="#/courses" data-action="back">${icon('back')} Back</a><div class="breadcrumbs"><a href="#/courses">Courses</a><span>/</span><span>${esc(c.category)}</span></div></div><section class="detail-hero"><div><span class="pill">${esc(c.level)} · Live on Zoom</span><h1>${esc(c.title)}</h1><div class="detail-rating">${ratingTag('course',c.id,c.rating)}<span>Student rating</span></div><p>${esc(c.description)}</p><div class="course-price large">${money(c.price,c.currency)} <small>one-time course fee</small></div><div class="actions">${c.access?'<span class="status">✓ Course access approved</span>':c.order?.status==='pending'?'<span class="status draft">Payment awaiting review</span>':`<a class="btn" href="#/checkout/${c.id}">${c.order?'Resubmit payment request':'Join this course'} ${icon('arrow')}</a>`}${user?.role==='admin'?`<a class="btn outline small" href="#/admin/course/${c.id}">Edit course</a>`:''}</div>${c.order?.admin_note?`<div class="demo-box"><b>Administrator note</b><br>${esc(c.order.admin_note)}</div>`:''}</div>${cover(c)}</section><section class="detail-section"><div class="section-head slim"><div><h2>Live lecture schedule</h2><p>Sessions take place on Zoom. Approved course members can access the meeting links.</p></div></div><div class="lecture-stack">${c.lectures.map(l=>lectureCard(l)).join('')||empty('Schedule coming soon','Your instructor will add session details and Zoom links here.')}</div></section><section class="detail-section"><div class="section-head slim"><div><h2>Ratings &amp; reviews</h2><p>What students think about this course.</p></div></div>${reviewsRoot('course',c.id)}</section></div>`;
}
async function schedule(){lectures=await api('/api/lectures');return `<div class="container bottom-space"><div class="pagehead"><div class="overline">Save a little time to learn</div><h1>Your next live lecture.</h1><p>All sessions happen on Zoom. Times below use your device’s time zone (${esc(browserZone())}).</p></div><div class="toolbar">${[['upcoming','Upcoming & live'],['all','All lectures'],['mine','My course lectures']].map(([value,label])=>`<button class="filter ${scheduleFilter===value?'selected':''}" data-action="schedule-filter" data-value="${value}">${label}</button>`).join('')}</div><div id="lecture-results" class="lecture-stack"></div></div>`;}
function filterLectures(){const el=$('#lecture-results');if(!el)return;const list=lectures.filter(l=>scheduleFilter==='all'||(scheduleFilter==='mine'?l.access:l.status==='scheduled'));el.innerHTML=list.map(l=>lectureCard(l)).join('')||empty(scheduleFilter==='mine'?'Your course schedule starts here':'No sessions on this list',scheduleFilter==='mine'?'Approved course enrollments unlock your lecture links.':'Check the noticeboard for your instructor’s next update.','#/courses');}
async function noticePage(){notices=await api('/api/notices');seenAt=new Date().toISOString();localStorage.setItem('medcircle-seen',seenAt);return `<div class="container bottom-space"><div class="pagehead"><div class="overline">Stay connected</div><h1>From your academy.</h1><p>Lecture announcements, schedule changes and course updates, in one place.</p></div><div class="notice-list">${notices.map(noticeCard).join('')||empty('You’re all caught up','No new announcements right now.')}</div>${!user?'<div class="demo-box">Sign in to see notices for courses you have access to. <a class="inline-link" href="#/login">Sign in</a></div>':''}</div>`;}
async function learning(){if(!user)return auth('login');const [all,orders,upcoming]=await Promise.all([api('/api/courses'),api('/api/my-orders'),api('/api/lectures')]);return `<div class="container bottom-space"><div class="pagehead"><div class="overline">Your learning circle</div><h1>Welcome back, ${esc(user.name.split(' ')[0])}.</h1><p>Your courses, payment updates and upcoming live lectures.</p></div><div class="section-head"><h2>Next in your calendar</h2><a class="textbtn" href="#/schedule">Full schedule ${icon('arrow')}</a></div><div class="lecture-stack">${upcoming.filter(l=>l.access&&l.status==='scheduled').slice(0,3).map(l=>lectureCard(l,true)).join('')||empty('No upcoming lectures in your courses','Approved course schedules will appear here.')}</div><section class="section"><div class="section-head"><h2>Your courses</h2><a class="textbtn" href="#/courses">Explore courses ${icon('arrow')}</a></div><div class="grid">${all.filter(c=>c.access).map(card).join('')||empty('Take your next step','Explore a course and submit your payment for access.','#/courses')}</div></section><div class="panel"><h2>Payment & access updates</h2>${orders.length?`<div class="tablewrap"><table><thead><tr><th>Course</th><th>Fee submitted</th><th>Status</th><th>Update</th></tr></thead><tbody>${orders.map(o=>`<tr><td class="titlecell"><a href="#/course/${o.course_id}"><b>${esc(o.course_title)}</b></a><small>${dateText(o.created)}</small></td><td>${money(o.amount,o.currency)}</td><td>${badge(o.status)}</td><td class="titlecell">${esc(o.admin_note|| (o.status==='pending'?'Your payment is waiting for manual verification.':o.status==='approved'?'Your course Zoom links are unlocked.':'Contact the academy or submit an updated request.'))}</td></tr>`).join('')}</tbody></table></div>`:empty('No payment requests yet','Requests and administrator decisions will appear here.')}</div></div>`;}
async function checkout(id){
 if(!user){sessionStorage.setItem('returnTo',location.hash);return auth('login');}
 const [c,payment]=await Promise.all([api('/api/courses/'+id),api('/api/payment-settings')]);checkoutCourse=c;
 if(c.access||c.order?.status==='pending')return `<div class="container section">${empty(c.access?'You already have access':'Your payment is under review',c.access?'Your course lectures are ready to explore.':'You’ll see the decision in My courses.','#/course/'+c.id,'View course')}</div>`;
 return `<div class="container section"><div class="checkout-layout"><section><div class="overline">A place in your next course</div><h1>Join the learning circle.</h1><p class="muted">Pay the course fee using the instructor’s instructions, then submit your reference for verification.</p><div class="payment-steps"><span>01 · Pay course fee</span><span>02 · Submit reference</span><span>03 · Admin approves</span></div>${payment.enabled?`<div class="panel"><h2>Payment instructions</h2><p class="preserve">${esc(payment.instructions)}</p><p class="hint">Questions? ${esc(payment.contact)}</p></div><form id="payment-form" class="panel"><h2>Submit your payment</h2><div class="form-error" role="alert"></div><label class="field">Transaction / payment reference<input name="reference" required maxlength="300" placeholder="Reference number from your payment receipt"></label>${uploadField('Payment screenshot (optional)','proof','','image/png,image/jpeg,image/webp',true)}<p class="hint">Payment screenshots are visible only to you and the administrator. Do not upload ID documents or patient information.</p><button class="btn" type="submit">Submit for verification ${icon('arrow')}</button><p class="hint">This form does not charge your card or transfer money. Access unlocks after the administrator verifies your payment.</p></form>`:empty('Enrollment opens soon','The administrator has not enabled payment instructions yet. No payment is being collected.')} </section><aside class="checkout-summary">${cover(c)}<div class="panel"><span class="pill">LIVE ZOOM COURSE</span><h2>${esc(c.title)}</h2><div class="course-price large">${money(c.price,c.currency)}</div><p class="hint">One-time payment for this course. No recurring subscription.</p><ul class="benefits"><li>Scheduled Zoom lecture links</li><li>Course notices and updates</li><li>Access through your student account</li></ul><a class="inline-link" href="#/course/${c.id}">Review course details</a></div></aside></div></div>`;
}

function youtube(url){try{const u=new URL(url);if(['www.youtube.com','youtube.com','m.youtube.com','www.youtube-nocookie.com'].includes(u.hostname)){const id=u.searchParams.get('v')||u.pathname.split('/').filter(Boolean).pop();if(/^[\w-]{11}$/.test(id))return id;}if(u.hostname==='youtu.be'&&/^[\w-]{11}$/.test(u.pathname.slice(1)))return u.pathname.slice(1);}catch{}return '';}
function player(url,title,vertical=false){const yt=youtube(url);return yt?`<iframe class="${vertical?'':'video-frame'}" src="https://www.youtube-nocookie.com/embed/${yt}" title="${esc(title)}" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture" allowfullscreen></iframe>`:`<video class="${vertical?'':'video-frame'}" controls preload="metadata" playsinline src="${esc(url)}" aria-label="${esc(title)}">Your browser cannot play this video.</video>`;}

async function reelPage(selected){reels=await api('/api/reels');if(selected)reels.sort((a,b)=>Number(b.id===selected)-Number(a.id===selected));return `<div class="container"><div class="pagehead"><div class="overline">From your medical learning circle</div><h1>A moment of learning. A little connection.</h1><p>Short medical education reels, course previews and instructor updates.</p></div><div class="reels-feed">${reels.map(r=>`<article class="feed-card">${r.video?player(r.video,r.title,true):`<div class="feed-display"><div class="overline">${esc(r.category)} / Academy reel</div><h2>${esc(r.title)}</h2><pre>${esc(r.caption)}</pre></div>`}<div class="feed-info"><h3>${esc(r.title)}</h3><div class="feed-rating">${ratingTag('reel',r.id,r.rating)}</div>${r.video?`<p>${esc(r.caption)}</p>`:''}<div class="feed-actions"><span>${esc(r.category)}</span><button class="btn small outline rate-btn" data-review-open data-type="reel" data-id="${r.id}" data-title="${esc(r.title)}">${icon('chat')} Reviews</button><button class="btn small light ${r.liked?'liked':''}" data-action="like" data-id="${r.id}" data-liked="${r.liked}" aria-pressed="${r.liked}">${icon('heart')} <span>${r.likes}</span></button></div></div></article>`).join('')||empty('Fresh reels are on the way','Check back soon for more bite-sized ideas.')}</div></div>`;}
function shell(content,section){return `<div class="app-layout"><aside class="sidebar"><div class="overline">Academy workspace</div>${[['overview','grid','Overview',''],['courses','book','Courses','/courses'],['lectures','calendar','Live lectures','/lectures'],['notices','bell','Noticeboard','/notices'],['reels','play','Reels','/reels'],['payments','wallet','Payments','/payments'],['users','users','Students','/users'],['settings','settings','Settings','/settings']].map(([key,i,label,p])=>`<a class="side-link ${key===section?'active':''}" href="#/admin${p}">${icon(i)}${label}</a>`).join('')}<div class="side-bottom">A connected academy.<br>A shared purpose.</div></aside><section class="workspace fade-in">${content}</section></div>`;}
function pagehead(title,description,action=''){return `<div class="pagehead"><div><h1>${title}</h1><p>${description}</p></div>${action}</div>`;}
function newButton(path,label){return `<a class="btn" href="#/admin/${path}/new">${icon('plus')} ${label}</a>`;}
function table(headers,rows){return `<div class="tablewrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows||`<tr><td colspan="${headers.length}">Nothing here yet.</td></tr>`}</tbody></table></div>`;}
function editActions(type,id,view=''){return `<div class="rowactions"><a class="btn small light" href="#/admin/${type}/${id}">Edit</a>${view?`<a class="btn small outline" href="${view}">View</a>`:''}<button class="btn small danger" data-action="delete-${type}" data-id="${id}">Delete</button></div>`;}
async function adminPage(section='overview'){
 if(!user)return auth('login');
 if(user.role!=='admin')return `<div class="container section">${empty('Administrator access required','Your courses and payment updates are available in My courses.','#/learning','My courses')}</div>`;
 if(section==='overview'){
  const [s,upcoming]=await Promise.all([api('/api/admin/stats'),api('/api/lectures?all=1')]);
  return shell(`${pagehead('Your academy, at a glance.','Keep your community learning, connected and informed.',newButton('lecture','Schedule lecture'))}<div class="stats">${[['Courses',s.courses,'Your course library'],['Students',s.students,'Registered accounts'],['Pending payments',s.pending,'Waiting for verification'],['Approved enrollments',s.approved,'Course access granted']].map(([label,n,hint])=>`<div class="stat"><small>${label}</small><b>${n}</b><span>${hint}</span></div>`).join('')}</div><div class="panel"><h2>Make the next connection.</h2><div class="quicklinks"><a class="quicklink" href="#/admin/lecture/new">${icon('calendar')}<b>Schedule a Zoom lecture</b><small>Add a time, topic and private meeting link.</small></a><a class="quicklink" href="#/admin/notice/new">${icon('bell')}<b>Post an announcement</b><small>Share what your students need to know.</small></a><a class="quicklink" href="#/admin/payments">${icon('wallet')}<b>Review course payments</b><small>Verify payments and approve access.</small></a></div></div><div class="panel"><h2>Next on the schedule</h2>${upcoming.filter(l=>l.status==='scheduled').slice(0,3).map(l=>lectureCard(l,true)).join('')||empty('A new session starts with you','Add a lecture and share it with your course members.')}</div><div class="panel"><h2>Recent access requests</h2>${s.recent.map(a=>`<div class="activity"><div><b>${esc(a.name)}</b><small>${esc(a.title)}</small></div>${badge(a.status)}</div>`).join('')||empty('No requests yet','Students’ payment submissions will appear here.')}</div>`,'overview');
 }
 if(section==='courses'){
  courses=await api('/api/courses?all=1');
  return shell(`${pagehead('Your medical courses','Set the syllabus and a separate one-time fee for each course.',newButton('course','New course'))}${table(['Course','Fee','Status','Sessions','Students','Actions'],courses.map(c=>`<tr><td class="titlecell"><b>${esc(c.title)}</b><small>${esc(c.category)}</small></td><td>${money(c.price,c.currency)}</td><td>${badge(c.published?'published':'draft')}</td><td>${c.lectureCount}</td><td>${c.students}</td><td>${editActions('course',c.id,'#/course/'+c.id)}</td></tr>`).join(''))}`,'courses');
 }
 if(section==='lectures'){
  lectures=await api('/api/lectures?all=1');
  return shell(`${pagehead('Live lecture schedule','All teaching takes place on Zoom. Meeting links are restricted to approved course members.',newButton('lecture','Schedule lecture'))}${table(['Lecture','When','Status','Zoom link','Actions'],lectures.map(l=>`<tr><td class="titlecell"><b>${esc(l.title)}</b><small>${esc(l.course_title)}</small></td><td>${esc(dateTime(l.starts_at))}<br><small>${l.duration} minutes</small></td><td>${badge(l.status)}</td><td>${l.hasLink?'Added':'Not added'}</td><td>${editActions('lecture',l.id)}</td></tr>`).join(''))}`,'lectures');
 }
 if(section==='notices'){
  const rows=await api('/api/notices?all=1');
  return shell(`${pagehead('Keep your circle informed.','Publish public announcements or private notices for approved course members.',newButton('notice','New notice'))}${table(['Notice','Audience','Status','Actions'],rows.map(n=>`<tr><td class="titlecell"><b>${n.pinned?'✦ ':''}${esc(n.title)}</b><small>${dateText(n.created)}</small></td><td class="titlecell">${n.course_id?esc(n.course_title):'Everyone'}</td><td>${badge(n.published?'published':'draft')}</td><td>${editActions('notice',n.id)}</td></tr>`).join(''))}`,'notices');
 }
 if(section==='reels'){
  reels=await api('/api/reels?all=1');
  return shell(`${pagehead('Your academy reels','Upload a short medical education reel or a course preview.',newButton('reel','New reel'))}${table(['Reel','Status','Likes','Actions'],reels.map(r=>`<tr><td class="titlecell"><b>${esc(r.title)}</b><small>${esc(r.category)}</small></td><td>${badge(r.published?'published':'draft')}</td><td>${r.likes}</td><td>${editActions('reel',r.id)}</td></tr>`).join(''))}`,'reels');
 }
 if(section==='payments'){
  const orders=await api('/api/admin/orders');
  return shell(`${pagehead('Payments & course access','Verify each payment in your receiving account before approving. Screenshots alone are not verification.','<a class="btn outline" href="#/admin/settings">Payment settings</a>')}<div class="toolbar"><select id="payment-filter" aria-label="Filter payment status">${['all','pending','approved','rejected','revoked'].map(s=>`<option value="${s}" ${paymentFilter===s?'selected':''}>${s==='all'?'All requests':s}</option>`).join('')}</select><span class="hint">Approve → unlock course Zoom links. Revoke → remove course access.</span></div>${table(['Student / course','Submitted fee','Reference / proof','Status','Actions'],orders.map(o=>`<tr data-payment="${o.status}"><td class="titlecell"><b>${esc(o.name)}</b><small>${esc(o.email)}</small><p class="hint">${esc(o.course_title)}</p></td><td>${money(o.amount,o.currency)}<br><small>${dateText(o.created)}</small></td><td class="titlecell"><b>${esc(o.reference)}</b>${o.proof?`<a class="inline-link" href="${esc(o.proof)}" target="_blank" rel="noopener">View private receipt ↗</a>`:'<small>No screenshot</small>'}</td><td>${badge(o.status)}${o.admin_note?`<p class="hint">${esc(o.admin_note)}</p>`:''}</td><td><div class="rowactions">${o.status==='pending'?`<button class="btn small" data-action="review-payment" data-status="approved" data-id="${o.id}">Approve</button><button class="btn small danger" data-action="review-payment" data-status="rejected" data-id="${o.id}">Reject</button>`:o.status==='approved'?`<button class="btn small danger" data-action="review-payment" data-status="revoked" data-id="${o.id}">Revoke access</button>`:'<small>Awaiting student resubmission</small>'}</div></td></tr>`).join(''))}<p id="payment-empty" class="hint" hidden>No requests match this filter.</p>`,'payments');
 }
 if(section==='users'){
  const users=await api('/api/admin/users');
  return shell(`${pagehead('Your community','View students, suspend access, or remove an account.')}<div class="toolbar"><div class="search">${icon('search')}<input id="user-search" placeholder="Search by name or email" aria-label="Search users"></div></div>${table(['User','Role','Status','Courses','Actions'],users.map(u=>`<tr data-user="${esc((u.name+' '+u.email).toLowerCase())}"><td class="titlecell"><b>${esc(u.name)}</b><small>${esc(u.email)}</small></td><td>${esc(u.role)}</td><td>${badge(u.status)}</td><td>${u.enrollments}</td><td>${u.role==='admin'?'<span class="hint">Protected administrator</span>':`<div class="rowactions"><button class="btn small light" data-action="suspend" data-id="${u.id}" data-status="${u.status}">${u.status==='active'?'Suspend':'Reactivate'}</button><button class="btn small danger" data-action="delete-user" data-id="${u.id}">Delete</button></div>`}</td></tr>`).join(''))}<p id="user-no-results" class="hint" hidden>No matching students.</p>`,'users');
 }
 const payment=await api('/api/payment-settings');
 return shell(`${pagehead('Academy settings','Configure payment instructions, then open enrollment.')}<form id="settings-form" class="panel editor-form"><div class="form-error" role="alert"></div><h2>Manual course payments</h2><p class="hint">Add your own bank or payment provider details. Students pay you outside this website; you verify the transaction and approve access.</p><label class="field">Payment instructions<textarea name="instructions" rows="7" maxlength="5000" placeholder="Payment method, account title, account number and instructions for the student…">${esc(payment.instructions)}</textarea></label>${field('Support contact','contact',payment.contact,'text','maxlength="200" placeholder="Email or WhatsApp number"')}<label class="check"><input type="checkbox" name="enabled" ${payment.enabled?'checked':''}> Enable payment submissions</label><p class="hint">Use your real receiving account details before accepting payments. Do not enter bank login credentials, card numbers or private keys.</p><button class="btn" type="submit">Save payment settings</button></form>${accountForm(false)}`,'settings');
}
function field(label,name,value='',type='text',extra=''){return `<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;}
function selectField(label,name,values,value){return `<label class="field">${label}<select name="${name}">${values.map(v=>`<option ${v===value?'selected':''}>${esc(v)}</option>`).join('')}</select></label>`;}
function courseSelect(all,selected='',allowAll=false){return `<label class="field">${allowAll?'Audience':'Course'}<select name="course_id" ${allowAll?'':'required'}>${allowAll?'<option value="">Everyone (public announcement)</option>':'<option value="">Choose a course</option>'}${all.map(c=>`<option value="${c.id}" ${c.id===selected?'selected':''}>${esc(c.title)}${c.published?'':' (draft)'}</option>`).join('')}</select></label>`;}
function uploadField(label,name,value='',accept='video/mp4,video/webm',proof=false){return `<label class="field">${label}<input name="${name}" value="${esc(value)}" ${proof?'type="hidden"':'placeholder="HTTPS URL, YouTube link, or upload below"'}><span class="file-upload"><small>Choose a file · Maximum ${proof?'5':'100'} MB</small><input type="file" data-upload="${name}" ${proof?'data-proof="true"':''} accept="${accept}" aria-label="Upload ${label}"></span><span class="hint upload-status"></span></label>`;}
function savebar(back,label='Save changes'){return `<div class="savebar"><button class="btn" type="submit">${icon('check')} ${label}</button><a href="#/admin/${back}" class="btn outline">Cancel</a></div>`;}
async function editor(type,id){
 if(user?.role!=='admin')return adminPage();
 const allCourses=await api('/api/courses?all=1');
 const plural={course:'courses',lecture:'lectures',notice:'notices',reel:'reels'}[type];
 const all=type==='course'?allCourses:await api('/api/'+plural+'?all=1');
 editing=id==='new'?null:all.find(x=>x.id===id);if(id!=='new'&&!editing)throw new Error('Item not found.');
 const r=editing||{};let fields='',description='';
 if(type==='course'){
  description='Course fee and overview live here. Schedule Zoom lectures in the Live lectures tab.';
  fields=`${field('Course title','title',r.title,'text','required maxlength="200"')}<label class="field">Course description / syllabus<textarea name="description" required rows="6" maxlength="5000">${esc(r.description)}</textarea></label><div class="form-grid">${field('Medical subject','category',r.category||'Medical sciences','text','required maxlength="60"')}${selectField('Level','level',['Foundation','Intermediate','Revision'],r.level||'Foundation')}${field('One-time course fee','price',r.price===undefined?'2500':(r.price/100).toFixed(2),'number','required min="1" max="1000000" step="0.01"')}${selectField('Currency','currency',['PKR','USD','GBP','EUR','AED','INR'],r.currency||'PKR')}${selectField('Cover color','color',['blue','green','purple','cyan','orange','yellow'],r.color||'blue')}${field('Cover symbol','icon',r.icon||'+','text','maxlength="5"')}</div>${uploadField('Course cover (optional)','thumbnail',r.thumbnail,'image/png,image/jpeg,image/webp')}<label class="check"><input name="published" type="checkbox" ${r.published?'checked':''}> Publish this course</label><p class="hint">Changing the fee applies to new requests. Existing submitted requests keep their original fee. Draft courses are hidden from students.</p>`;
 }
 if(type==='lecture'){
  description='Students see the schedule. Only approved course members can retrieve the Zoom link.';
  fields=`${courseSelect(allCourses,r.course_id)}${field('Lecture title','title',r.title,'text','required maxlength="200"')}${field('Instructor / speaker','speaker',r.speaker,'text','maxlength="100"')}<label class="field">Lecture details<textarea name="description" rows="4" maxlength="5000">${esc(r.description)}</textarea></label><div class="form-grid">${field('Start time (your local time)','starts_at',r.starts_at?localDateValue(r.starts_at):'','datetime-local','required')}${field('Duration in minutes','duration',r.duration||60,'number','required min="5" max="480"')}</div><p class="hint">You are entering time in ${esc(browserZone())}. Students see the same moment converted to their own device’s time zone.</p>${field('Private Zoom meeting link','zoom_url',r.zoom_url,'url','placeholder="https://zoom.us/j/…" maxlength="2000"')}<p class="hint">Create the meeting in your Zoom account, then paste its link here. This website does not create Zoom meetings. Never put meeting links in public descriptions or notices.</p>${selectField('Lecture status','status',['scheduled','cancelled','completed'],r.status||'scheduled')}`;
 }
 if(type==='notice'){
  description='Post a lecture announcement, a schedule change or a community update.';
  fields=`${field('Notice title','title',r.title,'text','required maxlength="200"')}<label class="field">Message<textarea name="body" required rows="8" maxlength="8000">${esc(r.body)}</textarea></label>${courseSelect(allCourses,r.course_id,true)}<p class="hint">A course audience limits this notice to approved members of that course. Keep Zoom links in Live lectures so course access is checked.</p><label class="check field"><input name="pinned" type="checkbox" ${r.pinned?'checked':''}> Pin this notice at the top</label><label class="check"><input name="published" type="checkbox" ${r.published?'checked':''}> Publish this notice</label>`;
 }
 if(type==='reel'){
  description='Share a short medical education video, instructor introduction or course preview.';
  fields=`${field('Reel title','title',r.title,'text','required maxlength="200"')}<div class="form-grid">${field('Subject / category','category',r.category||'Medical education','text','required maxlength="60"')}${selectField('Cover color','color',['blue','green','purple','cyan','orange','yellow'],r.color||'blue')}</div>${uploadField('Reel video','video',r.video)}<label class="field">Caption<textarea name="caption" rows="6" maxlength="4000">${esc(r.caption)}</textarea></label><p class="hint">A vertical MP4/WebM video (9:16) looks best. A YouTube link is also supported. Without a video, this is a readable preview card.</p><label class="check"><input name="published" type="checkbox" ${r.published?'checked':''}> Publish this reel</label>`;
 }
 return shell(`${pagehead(`${id==='new'?'Create':'Edit'} ${type}`,description,`<a class="btn outline" href="#/admin/${plural}">Back</a>`)}<form id="content-form" class="editor-form" data-type="${type}"><div class="form-error" role="alert"></div><div class="panel">${fields}</div>${savebar(plural)}</form>`,plural);
}
function accountForm(withTitle=true){return `${withTitle?pagehead('Your account','Keep your account details safe.'):''}<div class="panel"><h2>${esc(user.name)}</h2><p class="hint">${esc(user.email)} · ${esc(user.role)}</p><form id="password-form" class="editor-form"><div class="form-error" role="alert"></div>${field('Current password','currentPassword','','password','required autocomplete="current-password" maxlength="128"')}${field('New password','password','','password','required minlength="10" maxlength="128" autocomplete="new-password"')}<button class="btn">Update password</button></form></div><button class="btn outline" data-action="logout">${icon('logout')} Sign out</button>`;}
async function route(){
 const token=++routeToken,p=(location.hash.slice(1)||'/').split('/').filter(Boolean);
 header();main.innerHTML='<div class="loading">Opening your learning circle…</div>';
 try{
  let html;
  if(!p.length)html=await home();
  else if(p[0]==='courses')html=await catalogue();
  else if(p[0]==='course')html=await courseDetail(p[1]);
  else if(p[0]==='learning')html=await learning();
  else if(p[0]==='schedule')html=await schedule();
  else if(p[0]==='notices')html=await noticePage();
  else if(p[0]==='checkout')html=await checkout(p[1]);
  else if(p[0]==='reels')html=await reelPage(p[1]);
  else if(['login','signup'].includes(p[0]))html=auth(p[0]);
  else if(p[0]==='account')html=user?await accountPage(user,p[1],{card,lectureCard,badge}):auth('login');
  else if(p[0]==='admin')html=['course','lecture','notice','reel'].includes(p[1])?await editor(p[1],p[2]):await adminPage(p[1]);
  else html=`<div class="container section">${empty('This page isn’t in the schedule','Let’s get you back to your learning circle.','#/','Back home')}</div>`;
  if(token!==routeToken)return;
  main.innerHTML=html;header();filterCourses();filterLectures();filterPayments();hydrateReviews();
  main.classList.remove('fade-in');void main.offsetWidth;main.classList.add('fade-in');
  document.title=(p[0]?p[0][0].toUpperCase()+p[0].slice(1)+' · ':'')+'Cath Lab Insights';main.focus({preventScroll:true});
 }catch(e){if(token===routeToken)main.innerHTML=`<div class="container section">${empty('Something needs another try',esc(e.message),'#/','Back home')}</div>`;}
}
function reviewDialog(status){return new Promise(resolve=>{const dialog=$('#modal');const approve=status==='approved';dialog.innerHTML=`<h2>${approve?'Approve course access?':status==='rejected'?'Reject payment request?':'Revoke course access?'}</h2><p>${approve?'Confirm that the exact payment arrived in your receiving account. This grants access to the course Zoom links.':status==='rejected'?'Add a reason so the student can correct the payment request.':'This removes access to Zoom links. It does not issue a refund or stop a meeting already joined.'}</p><form method="dialog"><label class="field">${approve?'Note for student (optional)':'Reason for student'}<textarea name="note" maxlength="1000" ${approve?'':'required'}></textarea></label><div class="actions"><button class="btn" value="confirm">${approve?'Payment verified — approve':'Confirm'}</button><button class="btn outline" value="cancel" formnovalidate autofocus>Cancel</button></div></form>`;dialog.returnValue='cancel';dialog.addEventListener('close',()=>resolve(dialog.returnValue==='confirm'?{admin_note:dialog.querySelector('textarea').value}:null),{once:true});dialog.showModal();});}
function filterPayments(){let count=0;document.querySelectorAll('[data-payment]').forEach(row=>{row.hidden=paymentFilter!=='all'&&row.dataset.payment!==paymentFilter;if(!row.hidden)count++;});if($('#payment-empty'))$('#payment-empty').hidden=count>0;}
document.addEventListener('click',async e=>{
 const b=e.target.closest('[data-action]');if(!b)return;const action=b.dataset.action,id=b.dataset.id;
 try{
  if(action==='menu'){const open=$('#navlinks').classList.toggle('open');b.setAttribute('aria-expanded',String(open));return;}
  if(action==='fill-demo'){const form=$('#auth-form');form.elements.email.value=demoEmail;form.elements.password.value='Admin@12345';return;}
  if(action==='schedule-filter'){scheduleFilter=b.dataset.value;document.querySelectorAll('[data-action="schedule-filter"]').forEach(el=>el.classList.toggle('selected',el.dataset.value===scheduleFilter));filterLectures();return;}
  if(action==='back'){e.preventDefault();if(history.length>1)history.back();else location.hash='#/courses';return;}
  b.disabled=true;
  if(action==='delete-account'){const pw=await deleteAccountDialog();if(pw===null)return;await api('/api/account',{method:'DELETE',body:{password:pw}});user=null;notices=await api('/api/notices');toast('Your account was deleted.');location.hash='#/';await route();return;}
  if(action==='logout'){await api('/api/logout',{method:'POST',body:{}});user=null;notices=await api('/api/notices');location.hash='#/';await route();}
  if(action==='join-zoom'){
   const result=await api('/api/lectures/'+id+'/join');
   const dialog=$('#modal');dialog.innerHTML=`<h2>Your lecture is on Zoom.</h2><p>The meeting opens in a new tab. Check the lecture’s scheduled time before joining.</p><a class="btn full" href="${esc(result.url)}" target="_blank" rel="noopener noreferrer">Open Zoom meeting ${icon('arrow')}</a><form method="dialog"><button class="btn outline full modal-close">Close</button></form>`;dialog.showModal();
  }
  if(action==='like'){
   if(!user){sessionStorage.setItem('returnTo',location.hash);location.hash='#/login';return;}
   const liked=b.dataset.liked!=='true';await api(`/api/reels/${id}/like`,{method:'POST',body:{liked}});
   b.dataset.liked=String(liked);b.setAttribute('aria-pressed',String(liked));b.classList.toggle('liked',liked);b.querySelector('span').textContent=Number(b.querySelector('span').textContent)+(liked?1:-1);
  }
  if(action.startsWith('delete-')){
   const type=action.slice(7),plural={course:'courses',lecture:'lectures',notice:'notices',reel:'reels',user:'admin/users'}[type];
   if(!await confirmAction(`Delete this ${type}?`,type==='course'?'This permanently deletes the course, its lectures, notices and payment/access records. Existing students lose access. Consider saving it as a draft instead.':type==='user'?'This permanently removes the student account and its payment/access records.':'This removes the item permanently.'))return;
   await api(`/api/${plural}/${id}`,{method:'DELETE',body:{}});toast('Deleted successfully');await route();
  }
  if(action==='review-payment'){
   const value=await reviewDialog(b.dataset.status);if(!value)return;
   await api('/api/admin/orders/'+id,{method:'PATCH',body:{status:b.dataset.status,...value}});toast('Payment decision saved');await route();
  }
  if(action==='suspend'){
   const status=b.dataset.status==='active'?'suspended':'active';
   if(status==='suspended'&&!await confirmAction('Suspend this student?','The student will be signed out and cannot access the academy until reactivated.'))return;
   await api(`/api/admin/users/${id}`,{method:'PATCH',body:{status}});toast('Student access updated');await route();
  }
 }catch(err){toast(err.message);}finally{b.disabled=false;}
});
document.addEventListener('input',e=>{
 if(e.target.id==='course-search'){search=e.target.value;filterCourses();}
 if(e.target.id==='user-search'){let count=0;document.querySelectorAll('[data-user]').forEach(row=>{row.hidden=!row.dataset.user.includes(e.target.value.toLowerCase());if(!row.hidden)count++;});$('#user-no-results').hidden=count>0;}
});
document.addEventListener('change',async e=>{
 if(e.target.id==='category-filter'){category=e.target.value;filterCourses();}
 if(e.target.id==='payment-filter'){paymentFilter=e.target.value;filterPayments();}
 if(e.target.matches('[data-upload]')){
  const input=e.target,file=input.files[0];if(!file)return;
  const label=input.closest('label'),status=label.querySelector('.upload-status'),target=label.querySelector(`input[name="${input.dataset.upload}"]`),proof=!!input.dataset.proof,max=proof?5:100;
  if(file.size>max*1024*1024){status.textContent=`File is too large. Maximum ${max} MB.`;input.value='';return;}
  uploadsInFlight++;input.disabled=true;status.textContent='Uploading… Please wait before saving.';
  try{
   const r=await fetch('/api/upload'+(proof?'?kind=proof':''),{method:'POST',headers:{'Content-Type':'application/octet-stream'},body:file}),data=await r.json();
   if(!r.ok)throw new Error(data.error);
   if(input.accept.startsWith('image/')!==data.type.startsWith('image/'))throw new Error(input.accept.startsWith('image/')?'Select an image file.':'Select a video file.');
   target.value=data.url;status.textContent='✓ Uploaded. Submit or save to attach it.';
  }catch(err){status.textContent=err.message;}finally{uploadsInFlight--;input.disabled=false;input.value='';}
 }
});
document.addEventListener('submit',async e=>{
 const form=e.target;if(!['auth-form','content-form','password-form','settings-form','payment-form','profile-form'].includes(form.id))return;e.preventDefault();
 const error=form.querySelector('.form-error'),button=form.querySelector('button[type="submit"]')||form.querySelector('button:not([type="button"])');error.textContent='';
 if(uploadsInFlight){error.textContent='Wait for all uploads to finish before saving.';return;}
 button.disabled=true;
 try{
  const values=Object.fromEntries(new FormData(form));
  if(form.id==='auth-form'){
   const result=await api('/api/'+(form.dataset.mode==='signup'?'register':'login'),{method:'POST',body:values});user=result.user;
   notices=await api('/api/notices');const back=sessionStorage.getItem('returnTo');sessionStorage.removeItem('returnTo');
   const destination=back&&back.startsWith('#/')?back:user.role==='admin'?'#/admin':'#/learning';
   if(location.hash===destination)await route();else location.hash=destination;
   toast('Welcome to your learning circle.');
  }
  if(form.id==='content-form'){
   const type=form.dataset.type,plural={course:'courses',lecture:'lectures',notice:'notices',reel:'reels'}[type];
   const data={...values,published:!!form.elements.published?.checked,pinned:!!form.elements.pinned?.checked};
   if(type==='lecture'){data.starts_at=new Date(values.starts_at).toISOString();data.timezone=browserZone();data.duration=Number(values.duration);}
   await api('/api/'+plural+(editing?'/'+editing.id:''),{method:editing?'PUT':'POST',body:data});toast('Saved successfully');location.hash='#/admin/'+plural;
  }
  if(form.id==='settings-form'){await api('/api/admin/payment-settings',{method:'PUT',body:{...values,enabled:form.elements.enabled.checked}});toast('Payment instructions saved');}
  if(form.id==='payment-form'){
   await api('/api/courses/'+checkoutCourse.id+'/request-access',{method:'POST',body:{...values,expectedAmount:checkoutCourse.price,expectedCurrency:checkoutCourse.currency}});
   toast('Submitted. Your payment is waiting for verification.');location.hash='#/learning';
  }
  if(form.id==='profile-form'){const res=await api('/api/profile',{method:'PATCH',body:{name:values.name}});user=res.user;toast('Profile saved');await route();}
  if(form.id==='password-form'){await api('/api/account',{method:'PATCH',body:values});form.reset();toast('Password updated. Other sessions have been signed out.');}
 }catch(err){error.textContent=err.message;error.scrollIntoView({block:'center',behavior:'smooth'});}finally{button.disabled=false;}
});
document.addEventListener('play',e=>{if(e.target.tagName==='VIDEO')document.querySelectorAll('video').forEach(v=>{if(v!==e.target)v.pause();});},true);
window.addEventListener('hashchange',()=>{scrollTo(0,0);route();});
// Updates are in-app only: periodically refresh the unread notice count while signed in.
setInterval(async()=>{if(!user||document.hidden)return;try{notices=await api('/api/notices');header();}catch{}},60000);
try{const me=await api('/api/me');user=me.user;demo=me.demo;demoEmail=me.demoEmail||demoEmail;notices=await api('/api/notices');await route();}
catch(e){main.innerHTML=`<div class="container section">${empty('Start the server to begin','Open this project in VS Code, run npm start, then visit http://localhost:3000.')}</div>`;}